-- specs/012 P1: Budget Documents — the LEP and the Ordinance (docs/adr/0001).
-- Additive: new tables only, plus program_comments.program_id becoming
-- nullable beside a new budget_item_id. Generated by `prisma migrate diff` with
-- the repo's pre-existing, unrelated drift removed (see memory note
-- naga-preexisting-schema-drift), then the CHECKs Prisma cannot model appended.

-- CreateEnum
CREATE TYPE "BudgetDocumentKind" AS ENUM ('LEP', 'ORDINANCE');

-- CreateEnum
CREATE TYPE "BudgetDocumentStatus" AS ENUM ('DRAFT', 'SUBMITTED', 'ENACTED');

-- CreateEnum
CREATE TYPE "BudgetDocumentAuditAction" AS ENUM ('IMPORTED', 'EDITED', 'ACKNOWLEDGED', 'FINALIZED', 'RETIRED_SOURCE', 'RESTORED_SOURCE', 'COMMENT');

-- AlterTable
ALTER TABLE "program_comments" ADD COLUMN     "budget_item_id" TEXT,
ALTER COLUMN "program_id" DROP NOT NULL;

-- CreateTable
CREATE TABLE "budget_documents" (
    "id" TEXT NOT NULL,
    "budget_cycle_id" TEXT NOT NULL,
    "kind" "BudgetDocumentKind" NOT NULL,
    "status" "BudgetDocumentStatus" NOT NULL DEFAULT 'DRAFT',
    "source_document_name" TEXT,
    "finalized_at" TIMESTAMP(3),
    "finalized_by_user_id" TEXT,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "budget_documents_pkey" PRIMARY KEY ("id")
);

