-- A PPA records at most one source: an AIP program, an AIP PA, or the previous
-- stage's PPA (LEP → Ordinance).
ALTER TABLE "budget_items" ADD CONSTRAINT "budget_items_one_source"
    CHECK (num_nonnulls("source_program_id", "source_project_activity_id", "source_item_id") <= 1);

-- A root is its own root; a child is never its own root.
ALTER TABLE "budget_items" ADD CONSTRAINT "budget_items_root_consistent"
    CHECK (("parent_id" IS NULL) = ("root_item_id" = "id"));

-- Own amounts are never negative; the total includes the children, so it is
-- never below the row's own amount.
ALTER TABLE "budget_items" ADD CONSTRAINT "budget_items_amounts_nonnegative"
    CHECK ("ps" >= 0 AND "mooe" >= 0 AND "fe" >= 0 AND "co" >= 0
           AND "total" >= "ps" + "mooe" + "fe" + "co");

-- A comment belongs to exactly one thing: an AIP program or a document PPA
-- (the climate_change_tags pattern).
ALTER TABLE "program_comments" ADD CONSTRAINT "program_comments_one_target"
    CHECK (num_nonnulls("program_id", "budget_item_id") = 1);
